//! Parsing both schema versions against the synthetic fixtures (generated by
//! `tests/fixtures/generate.py`; no real health data lives in the repo).

use std::path::PathBuf;

use healthaccess_core::model::workout::{detect_schema, parse_workout, SchemaVersion, SCHEMA_V1};
use healthaccess_core::model::StepKind;
use healthaccess_core::{derive, V0_EXPORTER_ZONE_BOUNDS};
use serde_json::Value;

fn fixture(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name);
    std::fs::read_to_string(path).expect("fixture")
}

/// Copies of `examples/workouts` (synthetic, `healthaccess.workout.v1`).
const POOL: &str = "2026-05-14_0712_PoolSwim_7A1C3E90.json";
const ROW: &str = "2026-05-12_0630_IndoorRow_3F8B2D41.json";
/// Generated Phase 0 files (`tests/fixtures/v0/generate.py`) that keep the v0 converter covered.
const V0_POOL: &str = "2026-10-21_1030_PoolSwim_5C0D9A7E.json";
const V0_ROW: &str = "2026-09-09_0840_IndoorRow_9B4F2E61.json";

fn v0_fixture(name: &str) -> String {
    fixture(&format!("v0/{name}"))
}

fn raw_counts(text: &str) -> (usize, usize, usize) {
    let v: Value = serde_json::from_str(text).unwrap();
    let activities = v["activities"].as_array().unwrap();
    let steps = activities
        .iter()
        .filter(|a| {
            a.get("metadata")
                .and_then(|m| m.get("WOIntervalStepKeyPath"))
                .is_some()
        })
        .count();
    let laps = v["events"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|e| e["type"] == 3)
        .count();
    let hr = v["hr_series"].as_array().unwrap().len();
    (steps, laps, hr)
}

#[test]
fn v0_pool_swim_derives_steps_laps_and_zones() {
    let text = v0_fixture(V0_POOL);
    assert_eq!(detect_schema(&text).unwrap(), SchemaVersion::V0);
    let (steps, laps, hr) = raw_counts(&text);
    let w = parse_workout(&text).unwrap();

    assert_eq!(w.schema, SCHEMA_V1);
    assert_eq!(w.id, "5C0D9A7E-1B2C-4D3E-8F4A-6B7C8D9E0F11");
    assert_eq!(w.activity, "pool_swim");
    assert_eq!(w.source, "Apple Watch");
    assert_eq!(w.distance_m, Some(1200.0));
    assert_eq!(w.pool_length_m, Some(50.0));
    assert_eq!(w.avg_hr, Some(127.0));
    assert_eq!(
        w.max_hr,
        Some(158.0),
        "max HR derived from the series (v0 files carry no aggregate)"
    );
    assert_eq!(w.hr_series.len(), hr);
    assert_eq!(w.steps.len(), steps);
    assert_eq!(w.laps.len(), laps);

    let z = w.zones.as_ref().expect("zones carried over");
    assert_eq!(z.bounds, V0_EXPORTER_ZONE_BOUNDS.to_vec());
    assert_eq!(
        (
            z.seconds.z1,
            z.seconds.z2,
            z.seconds.z3,
            z.seconds.z4,
            z.seconds.z5
        ),
        (1299, 180, 415, 0, 0)
    );
    assert_eq!(z.seconds.z12_pct().map(|p| p.round()), Some(78.0));

    let warm = &w.steps[0];
    assert_eq!(warm.key, "0.0.0");
    assert_eq!(warm.kind, StepKind::Warmup);
    assert_eq!(warm.goal_met, Some(true));
    assert_eq!(warm.duration_s, 120.0);

    let drill = w.steps.iter().find(|s| s.key == "2.1.0").unwrap();
    assert_eq!(drill.kind, StepKind::Work);
    assert_eq!(drill.pace_s_per_100m, Some(94.2)); // 49 s over 52 m
    let rest = w.steps.iter().find(|s| s.key == "2.1.1").unwrap();
    assert_eq!(rest.kind, StepKind::Recovery);
    assert_eq!(rest.pace_s_per_100m, None, "10 m of drift gets no pace");

    let last = w.steps.last().unwrap();
    assert_eq!(last.key, "4.0.0");
    assert_eq!(last.kind, StepKind::Cooldown, "trailing single-step block");
    assert_eq!(
        last.goal_met, None,
        "HealthKit did not record success for the last step"
    );

    let free = w
        .laps
        .iter()
        .filter(|l| l.stroke.as_deref() == Some("freestyle"))
        .count();
    assert!(free >= 15, "{free}");
    assert!(w.laps.iter().all(|l| l.duration_s > 0.0));
    assert!(w.laps[0].swolf.unwrap() > 60.0);

    let cc = derive::cardiac_cost(&w).expect("swim has cardiac cost");
    assert_eq!(cc.best_100_pace_s, 108.0, "{cc:?}"); // step 3.1.0: 100 m in 1:48
    assert_eq!(cc.beats_per_100m, 228.6);
    assert!(cc.basis.starts_with("step 3.1.0"));

    let rec = w.recovery_hr.expect("end HR");
    assert!(rec.end.is_some());

    let line = derive::summary_line(&w, derive::zones_for(&w, &V0_EXPORTER_ZONE_BOUNDS).as_ref());
    assert!(line.starts_with("2026-10-21 Pool swim · 1200 m · 31:35 · avg HR 127 (max 158) · Z1–2 78% · effort unrated"), "{line}");
}

#[test]
fn v0_indoor_row_has_steps_without_distance() {
    let text = v0_fixture(V0_ROW);
    let (steps, laps, _) = raw_counts(&text);
    let w = parse_workout(&text).unwrap();
    assert_eq!(w.activity, "indoor_row");
    assert_eq!(w.distance_m, None);
    assert_eq!(w.steps.len(), steps);
    assert_eq!(w.laps.len(), laps);
    assert!(w
        .steps
        .iter()
        .all(|s| s.distance_m.is_none() && s.pace_s_per_100m.is_none()));
    assert_eq!(w.steps[0].kind, StepKind::Warmup);
    assert_eq!(w.steps[1].key, "1.0.0");
    assert_eq!(w.steps[1].kind, StepKind::Work);
    assert_eq!(w.steps[3].key, "2.0.1");
    assert_eq!(
        w.steps[3].kind,
        StepKind::Recovery,
        "odd time-only step → recovery without a plan"
    );
    assert_eq!(w.steps.last().unwrap().key, "7.0.0");
    assert_eq!(w.steps.last().unwrap().kind, StepKind::Cooldown);
    assert!(
        derive::cardiac_cost(&w).is_none(),
        "cardiac cost is a swim metric"
    );
    assert_eq!(
        w.metadata.get("HKIndoorWorkout").map(String::as_str),
        Some("1")
    );
}

#[test]
fn v1_document_parses_and_round_trips() {
    let v1 = serde_json::json!({
        "schema": "healthaccess.workout.v1", "healthaccess_version": "0.2.0",
        "id": "7A1C3E90-5B2D-4F61-9C8E-2A7D40B6E1F3", "activity": "pool_swim",
        "source": "Apple Watch",
        "start": "2026-05-14T05:12:04Z", "end": "2026-05-14T05:48:10Z", "duration_s": 2166,
        "distance_m": 1200, "active_kcal": 339, "avg_hr": 129, "max_hr": 162, "pool_length_m": 50,
        "zones": {"bounds": [133,146,159,171], "seconds": {"z1":1500,"z2":420,"z3":180,"z4":66,"z5":0}},
        "plan_ref": {"plan_id": "2026-05-13T19:02:11Z-s12", "name": "S12"},
        "steps": [{"key": "2.1.0", "block": 2, "rep": 1, "step": 0, "label": "6-3-6", "kind": "work",
                   "start": "2026-05-14T05:22:10Z", "end": "2026-05-14T05:22:58Z", "duration_s": 48,
                   "distance_m": 50.0, "avg_hr": 101, "goal_met": true, "pace_s_per_100m": 96.0}],
        "laps": [{"start": "2026-05-14T05:14:00Z", "end": "2026-05-14T05:14:52Z", "duration_s": 52, "stroke": "freestyle", "swolf": 72.0}],
        "hr_series": [["2026-05-14T05:12:10Z", 84], ["2026-05-14T05:12:15Z", 85.6]],
        "recovery_hr": {"end": 121, "1min": 115, "2min": 109},
        "effort": 6, "feel": "legs heavy", "metadata": {"HKLapLength": "50 m", "HKIndoorWorkout": 0}
    });
    let text = serde_json::to_string(&v1).unwrap();
    assert_eq!(detect_schema(&text).unwrap(), SchemaVersion::V1);
    let w = parse_workout(&text).unwrap();
    assert_eq!(w.healthaccess_version.as_deref(), Some("0.2.0"));
    assert_eq!(w.effort, Some(6));
    assert_eq!(w.plan_ref.as_ref().unwrap().name.as_deref(), Some("S12"));
    assert_eq!(w.steps[0].label.as_deref(), Some("6-3-6"));
    assert_eq!(w.hr_series[1].bpm, 86, "fractional bpm rounds");
    assert_eq!(w.recovery_hr.unwrap().one_min, Some(115));
    assert_eq!(
        w.metadata["HKIndoorWorkout"], "0",
        "non-string metadata is stringified"
    );
    assert_eq!(w.display_name(), "S12");

    let back: Value = serde_json::to_value(&w).unwrap();
    assert_eq!(
        back["hr_series"][0],
        serde_json::json!(["2026-05-14T05:12:10Z", 84])
    );
    assert_eq!(back["recovery_hr"]["1min"], 115);
    assert_eq!(back["steps"][0]["kind"], "work");
    let line = derive::summary_line(&w, derive::zones_for(&w, &V0_EXPORTER_ZONE_BOUNDS).as_ref());
    assert!(
        line.contains("Pool swim \"S12\"") && line.contains("effort 6/10"),
        "{line}"
    );
}

#[test]
fn activities_without_key_paths() {
    let mk = |acts: Value| {
        serde_json::json!({
            "schema": "tide.workout.v0", "uuid": "AAAAAAAA-0000-4000-8000-000000000000", "activity": 13,
            "source": "Watch", "start": "2026-10-22T10:00:00Z", "end": "2026-10-22T11:00:00Z", "duration_s": 3600,
            "hr_series": [], "activities": acts, "events": [], "metadata": {}
        })
        .to_string()
    };
    let lone = parse_workout(&mk(serde_json::json!([{"kind": 13, "start": "2026-10-22T10:00:00Z", "end": "2026-10-22T11:00:00Z"}]))).unwrap();
    assert!(
        lone.steps.is_empty(),
        "a lone activity is the workout itself"
    );
    let multi = parse_workout(&mk(serde_json::json!([
        {"kind": 13, "start": "2026-10-22T10:00:00Z", "end": "2026-10-22T10:30:00Z", "distance_m": 9000},
        {"kind": 37, "start": "2026-10-22T10:30:00Z", "end": "2026-10-22T11:00:00Z", "distance_m": 5000}
    ])))
    .unwrap();
    assert_eq!(multi.steps.len(), 2);
    assert_eq!(
        (
            multi.steps[1].key.as_str(),
            multi.steps[1].block,
            multi.steps[1].rep,
            multi.steps[1].step
        ),
        ("1", 1, 0, 0)
    );
}

#[test]
fn pre_rename_tags_and_version_key_are_accepted_as_aliases() {
    // written by the app before the rename to Health Access MCP
    let legacy_v1 = r#"{"schema":"tide.workout.v1","tide_version":"0.2.0","id":"7A1C3E90-5B2D-4F61-9C8E-2A7D40B6E1F3",
        "activity":"pool_swim","source":"Watch","start":"2026-05-14T05:12:04Z","end":"2026-05-14T05:48:10Z",
        "duration_s":2166,"zones":null,"steps":[],"laps":[],"hr_series":[],"metadata":{}}"#;
    assert_eq!(detect_schema(legacy_v1).unwrap(), SchemaVersion::V1);
    assert_eq!(
        healthaccess_core::model::workout::schema_tag(legacy_v1).as_deref(),
        Some("tide.workout.v1")
    );
    let w = parse_workout(legacy_v1).unwrap();
    assert_eq!(w.healthaccess_version.as_deref(), Some("0.2.0"));
    assert_eq!(w.activity, "pool_swim");
    // the Phase 0 fixtures carry the v0 alias
    assert_eq!(
        detect_schema(&v0_fixture(V0_POOL)).unwrap(),
        SchemaVersion::V0
    );
    assert_eq!(
        healthaccess_core::model::workout::schema_tag(&v0_fixture(V0_POOL)).as_deref(),
        Some("tide.workout.v0")
    );
    // the v1 example copies carry the current tag
    assert_eq!(detect_schema(&fixture(POOL)).unwrap(), SchemaVersion::V1);
    assert_eq!(SCHEMA_V1, "healthaccess.workout.v1");
}

#[test]
fn v1_examples_carry_plan_labels_and_apple_effort() {
    let w = parse_workout(&fixture(POOL)).unwrap();
    assert_eq!(w.schema, SCHEMA_V1);
    assert_eq!(w.id, "7A1C3E90-5B2D-4F61-9C8E-2A7D40B6E1F3");
    assert_eq!(w.healthaccess_version.as_deref(), Some("0.4.0"));
    assert_eq!(w.plan_ref.as_ref().unwrap().name.as_deref(), Some("S12"));
    assert_eq!(w.effort, Some(6));
    assert_eq!(w.effort_source.as_deref(), Some("apple"));
    assert_eq!(w.effort_estimated, Some(5.0));
    assert!(
        w.zones.is_none(),
        "v0.4 files carry no zones; the Rust side computes them"
    );
    assert_eq!(w.steps.len(), 24);
    assert_eq!(w.laps.len(), 24);
    assert_eq!(w.hr_series.len(), 431);
    assert_eq!(
        w.steps[0].label.as_deref(),
        Some("FR easy, find your breathing")
    );
    assert_eq!(w.steps[0].kind, StepKind::Warmup);
    assert_eq!(w.steps[3].key, "1.0.2");
    assert_eq!(w.steps[3].kind, StepKind::Recovery);
    assert!(w.steps[3].label.is_none());
    assert_eq!(w.steps.last().unwrap().kind, StepKind::Cooldown);
    let cc = derive::cardiac_cost(&w).unwrap();
    assert_eq!(cc.best_100_pace_s, 132.0);
    assert_eq!(cc.beats_per_100m, 283.8);
    assert_eq!(cc.basis, "step 2.3.0 100 m in 2:12");
    assert_eq!(
        derive::summary_line(&w, derive::zones_for(&w, &V0_EXPORTER_ZONE_BOUNDS).as_ref()),
        "2026-05-14 Pool swim \"S12\" · 1200 m · 36:06 · avg HR 129 (max 162) · Z1–2 93% · effort 6/10 (apple) · best FR 100 2:12 → 284 beats/100 m"
    );
    let row = parse_workout(&fixture(ROW)).unwrap();
    assert_eq!(row.activity, "indoor_row");
    assert_eq!(row.effort, Some(7));
    assert_eq!(row.steps.len(), 10);
    assert!(derive::cardiac_cost(&row).is_none());
}

#[test]
fn unknown_schema_is_rejected() {
    let err = parse_workout(r#"{"schema":"tide.workout.v9","id":"x"}"#).unwrap_err();
    assert!(matches!(err, healthaccess_core::Error::Schema(_)), "{err}");
    let err = parse_workout(r#"{"schema":"healthaccess.workout.v9","id":"x"}"#).unwrap_err();
    assert!(matches!(err, healthaccess_core::Error::Schema(_)), "{err}");
    let err = parse_workout(r#"{"foo":1}"#).unwrap_err();
    assert!(matches!(err, healthaccess_core::Error::Schema(_)), "{err}");
}
